"""Queue ion guard. max_attempts includes the initial measurement.

Required parameters: threshold_a, threshold_b, threshold_c (summed counts).
Optional: fpga, sequence_path, exposure_us, settle_us, max_attempts,
timeout_s, retry_delay_s. DAC hooks below are deliberately not implemented.
"""
import math
from pathlib import Path

from labremote.runtime.workflow_result import WorkflowResult
from labremote.runtime.errors import OperationCancelled


def swap_ea(devices):
    """Connect EA DAC here, wait for completion, then return True.

    Example shape: devices.dac('dac_ea').run_sequence(sequence).wait()
    Raise on failure. False means no recovery was performed.
    """
    return False


def swap_ec(devices):
    """Connect EC DAC here, wait for completion, then return True."""
    return False


def classify(a, b, c):
    if not b and a and c:
        return 'normal'
    if b:
        if not a and not c:
            return 'swap_ea_then_ec'
        if not a:
            return 'swap_ea'
        if not c:
            return 'swap_ec'
        return 'recheck'
    return 'ion_loss_suspected'


def main(devices):
    try:
        return _run(devices)
    except OperationCancelled:
        raise
    except Exception as exc:
        # An ion guard failure must stop the queue even with on_failure=skip.
        return WorkflowResult(status='failed', continue_allowed=False,
                              cleanup_status='unknown',
                              reason=f'Ion check error: {type(exc).__name__}: {exc}')


def _run(devices):
    p = devices.parameters
    attempts = p.get('max_attempts', 3)
    if type(attempts) is not int or not 1 <= attempts <= 10000:
        raise ValueError('max_attempts must be an integer in 1..10000')
    thresholds = []
    for name in ('threshold_a', 'threshold_b', 'threshold_c'):
        value = p[name]
        if type(value) is not int or not 1 <= value <= 65535:
            raise ValueError(f'{name} must be an integer in 1..65535')
        thresholds.append(value)
    delay = p.get('retry_delay_s', 0.1)
    if (isinstance(delay, bool) or not isinstance(delay, (int, float))
            or not math.isfinite(delay) or delay < 0):
        raise ValueError('retry_delay_s must be finite and nonnegative')
    sequence_path = p.get('sequence_path', str(
        Path(__file__).resolve().parents[1] / 'sequences' / 'ion_check_sequence.py'))
    history = []
    fpga = devices.fpga(p.get('fpga', 'fpga_local'))

    def finish(ok, reason):
        return WorkflowResult(
            status='completed' if ok else 'failed', reason=reason,
            continue_allowed=ok,
            metrics={'attempts_used': len(history), 'max_attempts': attempts,
                     'decision': history[-1]['decision']},
            value={'thresholds': dict(zip(('a', 'b', 'c'), thresholds)),
                   'history': history})

    for attempt in range(1, attempts + 1):
        devices.wait(0)  # Honor cancellation before every acquisition.
        result = fpga.run_sequence_file(
            sequence_path,
            parameters={'exposure_us': p.get('exposure_us', 1000),
                        'settle_us': p.get('settle_us', 100)},
            timeout_s=p.get('timeout_s', 5), max_rows=1).wait()
        rows = result.get('rows')
        if (result.get('stopped') is not True or not isinstance(rows, list)
                or len(rows) != 1 or len(rows[0]) != 4 or rows[0][3] != 0x10):
            return WorkflowResult(status='failed', continue_allowed=False,
                                  reason='Ion check: invalid FIFO result',
                                  value={'history': history, 'invalid_result': result})
        counts = rows[0][:3]
        if any(type(v) is not int or not 0 <= v <= 65535 for v in counts):
            return WorkflowResult(status='failed', continue_allowed=False,
                                  reason='Ion check: invalid counts',
                                  value={'history': history, 'invalid_result': result})
        bright = [v >= t for v, t in zip(counts, thresholds)]
        decision = classify(*bright)
        entry = {'attempt': attempt, 'counts': dict(zip(('a', 'b', 'c'), counts)),
                 'bright': dict(zip(('a', 'b', 'c'), bright)),
                 'decision': decision, 'swaps': [],
                 'sequence_sha256': result.get('sha256')}
        history.append(entry)
        print(f'Ion check {attempt}/{attempts}: {entry}')
        if decision == 'normal':
            return finish(True, 'Ion check passed')
        if attempt == attempts:
            break  # Never perform a swap without a remaining verification attempt.
        targets = {'swap_ea': [('EA', swap_ea)], 'swap_ec': [('EC', swap_ec)],
                   'swap_ea_then_ec': [('EA', swap_ea), ('EC', swap_ec)]}.get(decision, [])
        for chamber, hook in targets:
            devices.wait(0)
            performed = hook(devices)
            if performed is not True and performed is not False:
                return finish(False, f'{chamber} swap hook must return True or False')
            entry['swaps'].append({'chamber': chamber, 'performed': performed})
            if not performed:
                print(f'{chamber} DAC swap is not connected; remeasurement only')
                break  # In a dual swap, do not run EC before EA was performed.
        devices.wait(delay)

    return finish(False, f'Ion check did not reach normal state after {attempts} measurements: '
                  + history[-1]['decision'])

"""Measure EA then EC SPAM using frozen settings and externally configured MW."""
from pathlib import Path
from labremote.runtime.workflow_result import WorkflowResult


def main(devices):
    p = devices.parameters
    fpga = devices.fpga(p['fpga'])
    reports = {}
    paths = []
    for chamber in ('EA', 'EC'):
        devices.wait(0)
        directory = (str(Path(devices.run_directory) / chamber)
                     if devices.run_directory else p.get('directory'))
        report = fpga.run_spam(
            chamber, settings=p['settings'][chamber], directory=directory,
            frequency_hz=p.get('frequency_hz', {}).get(chamber)).wait()
        reports[chamber] = report
        if isinstance(report, dict) and report.get('folder'):
            paths.append(report['folder'])
        if not isinstance(report, dict) or report.get('status') != 'completed':
            return WorkflowResult(
                status='cancelled' if isinstance(report, dict) and report.get('status') == 'cancelled' else 'failed',
                reason=f'{chamber} SPAM did not complete', continue_allowed=False,
                result_paths=paths, value=reports)
    return WorkflowResult(result_paths=paths, value=reports)

"""Use after an external MW setup workflow; this workflow controls only FPGA."""
def main(devices):
    p = devices.parameters
    if not p.get('fpga') or 'settings' not in p:
        raise ValueError('Entanglement requires parameters.fpga and frozen settings')
    return devices.fpga(p['fpga']).run_entanglement(
        settings=p['settings'], directory=devices.run_directory or p.get('directory')).wait()

