        bright = [v >= t for v, t in zip(counts, thresholds)]
        decision = classify(*bright)
        entry = {'attempt': attempt, 'counts': dict(zip(('a', 'b', 'c'), counts)),
                 'bright': dict(zip(('a', 'b', 'c'), bright)),
                 'decision': decision, 'swaps': [],
                 'sequence_sha256': result.get('sha256')}
        history.append(entry)
        print(f'Ion check {attempt}/{attempts}: {entry}')
        if decision == 'normal':
            return finish(True, 'Ion check passed')
        if attempt == attempts:
            break  # Never perform a swap without a remaining verification attempt.
        targets = {'swap_ea': [('EA', swap_ea)], 'swap_ec': [('EC', swap_ec)],
                   'swap_ea_then_ec': [('EA', swap_ea), ('EC', swap_ec)]}.get(decision, [])
        for chamber, hook in targets:
            devices.wait(0)
            performed = hook(devices)
            if performed is not True and performed is not False:
                return finish(False, f'{chamber} swap hook must return True or False')
            entry['swaps'].append({'chamber': chamber, 'performed': performed})
            if not performed:
                print(f'{chamber} DAC swap is not connected; remeasurement only')
                break  # In a dual swap, do not run EC before EA was performed.
        devices.wait(delay)

    return finish(False, f'Ion check did not reach normal state after {attempts} measurements: '
                  + history[-1]['decision'])

